fn find(table: &[(u32, &'static str)], v: u32) -> Option<&'static str> {
    table.binary_search_by_key(&v, |(k, _)| *k).ok().map(|i| table[i].1)
}

/// An RPC function's name, `"?"` past the table
pub fn function(f: u32) -> &'static str {
    FUNCTIONS.get(f as usize).copied().unwrap_or("?")
}

/// A control command's name, if the headers name it
pub fn control(cmd: u32) -> Option<&'static str> {
    find(CONTROLS, cmd)
}

/// A class's name, if the headers name it
pub fn class(c: u32) -> Option<&'static str> {
    find(CLASSES, c)
}
